      syntax: [["Test-NetConnection Ziel", "ICMP-Test mit Schnittstelleninformationen."], ["Test-NetConnection Ziel -Port 443", "Prüft einen TCP-Verbindungsaufbau. Das ist kein Nachweis eines zusätzlich erfolgreichen ICMP-Tests."], ["Test-NetConnection Ziel -TraceRoute", "Wegverfolgung statt Porttest."]],
