      deutung: [["TcpTestSucceeded True", "Eine TCP-Verbindung zum Port wurde aufgebaut. Der Port ist erreichbar, das beweist aber nicht, dass die Anwendung korrekt arbeitet."], ["TcpTestSucceeded False", "Verbindung kam nicht zustande: Dienst aus, Port geschlossen, Firewall oder Route. Weitere Schritte nötig."], ["RemoteAddress", "Zeigt, welche Adresse der Name ergeben hat."], ["PingSucceeded", "Wird nur bei ICMP-Test ausgegeben; kann falsch sein, wenn ICMP gefiltert ist."]],
      fehler: [["WARNING: TCP connect to (…) failed", "Port nicht erreichbar: Dienst läuft nicht, Firewall blockiert oder falsches Ziel."], ["WARNING: Name resolution of x failed", "DNS-Auflösung fehlgeschlagen; zuerst Resolve-DnsName prüfen."], ["Cmdlet unter Linux/macOS nicht vorhanden", "Es gehört zum Windows-Modul NetTCPIP."]],
      rechte: "Keine besonderen Rechte nötig.",
