      uebung: { frage: "TcpTestSucceeded ist True für Port 443. Was folgt sicher daraus?", optionen: ["Eine TCP-Verbindung zum Port ließ sich aufbauen; ob die Anwendung korrekt arbeitet, ist damit nicht bewiesen.", "Die Website ist fehlerfrei.", "Der Server ist sicher."], richtig: 0,
        erklaerung: "Ein erfolgreicher Verbindungsaufbau zeigt nur, dass etwas auf dem Port antwortet." },
